import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 상신 직후 결재 진행 상태는 '결재대기' (BEHAVIOR.md 값의 출처)
const SUBMITTED_STATUS = '결재대기';
const DRAFT_STATUS = '기안';

@Controller('api/v1')
export class FnSfr03001Controller {
  @Post('/approval-documents/:approvalDocumentId/submit')
  @HttpCode(200)
  async submitApprovalDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const idText = req.params['approvalDocumentId'];
    if (typeof idText !== 'string' || !/^[0-9]+$/.test(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재문서 ID가 올바르지 않습니다.');
    }
    const lines = data['approvalLines'];
    if (lines !== undefined && lines !== null && !Array.isArray(lines)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재선은 목록 형식이어야 합니다.');
    }
    return transaction(async (db) => {
      const docs = await db.query(
        'SELECT approval_document_id AS "approvalDocumentId", approval_status AS "approvalStatus", drafter_department_id AS "departmentId" ' +
          'FROM approval_document WHERE approval_document_id = CAST(:id AS bigint) FOR UPDATE',
        { id: idText },
      );
      if (docs.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '기안문이 존재하지 않습니다.');
      }
      const doc = docs[0];
      if (doc['approvalStatus'] !== DRAFT_STATUS) {
        throw new ApiError(409, 'APPROVAL_DOCUMENT_ALREADY_SUBMITTED', '이미 상신된 문서입니다.');
      }
      if (!Array.isArray(lines) || lines.length === 0) {
        throw new ApiError(422, 'APPROVAL_LINE_REQUIRED', '결재선을 지정해 주세요.');
      }
      // 가정: 부서 전용 문서번호 규칙을 먼저 쓰고, 없으면 전사 공통 규칙(부서 NULL)을 쓴다.
      // 가정: 채번 단위 변경 시 순번 초기화 기준 컬럼이 없어 순번은 계속 증가시킨다.
      const rules = await db.query(
        'SELECT numbering_rule_id AS "ruleId" FROM numbering_rule ' +
          "WHERE target_type = 'DOCUMENT' AND (department_id = CAST(:deptId AS bigint) OR department_id IS NULL) " +
          'ORDER BY (department_id IS NULL) ASC, numbering_rule_id ASC LIMIT 1 FOR UPDATE',
        { deptId: String(doc['departmentId']) },
      );
      if (rules.length === 0) {
        throw new ApiError(502, 'APPROVAL_SUBMIT_FAILED', '문서번호 채번 규칙이 없어 상신하지 못했습니다.');
      }
      const numbered = await db.query(
        'UPDATE numbering_rule SET current_sequence = COALESCE(current_sequence, 0) + 1, updated_at = now() ' +
          'WHERE numbering_rule_id = CAST(:ruleId AS bigint) ' +
          "RETURNING COALESCE(prefix, '') || '-' || to_char(now(), CASE reset_unit WHEN 'DAY' THEN 'YYYYMMDD' WHEN 'MONTH' THEN 'YYYYMM' ELSE 'YYYY' END) " +
          "|| '-' || lpad(current_sequence::text, digits, '0') AS \"documentNumber\"",
        { ruleId: String(rules[0]['ruleId']) },
      );
      const rows = await db.query(
        'UPDATE approval_document SET document_number = :documentNumber, approval_status = :status, ' +
          'submitted_at = now(), updated_at = now() ' +
          'WHERE approval_document_id = CAST(:id AS bigint) ' +
          'RETURNING approval_document_id AS "approvalDocumentId", approval_status AS "approvalStatus", submitted_at AS "submittedAt"',
        { documentNumber: numbered[0]['documentNumber'], status: SUBMITTED_STATUS, id: idText },
      );
      return rows[0];
    });
  }
}

