import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateText,
  Drawer,
  Field,
  Form,
  LookupSelect,
  RefName,
  Tiles,
  TextInput,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

type Mode = { kind: 'create' } | { kind: 'submit'; row: Row } | null;

export default function FnSfr03001Page({ role, notify }: PageProps) {
  const [rows, setRows] = useState<Row[]>([]);
  const [mode, setMode] = useState<Mode>(null);
  const [formId, setFormId] = useState<number | string>('');
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [bizType, setBizType] = useState('');
  const [bizId, setBizId] = useState('');
  const [lines, setLines] = useState<(number | string)[]>(['']);

  const draftCount = rows.filter((r) => r['approvalStatus'] === '기안').length;
  const submittedCount = rows.length - draftCount;

  function openCreate() {
    setFormId('');
    setTitle('');
    setBody('');
    setBizType('');
    setBizId('');
    setMode({ kind: 'create' });
  }

  function openSubmit(row: Row) {
    setLines(['']);
    setMode({ kind: 'submit', row });
  }

  async function create() {
    if (formId === '') throw new Error('결재양식을 선택하세요.');
    if (title.trim() === '') throw new Error('문서 제목을 입력하세요.');
    if (bizType.trim() === '') throw new Error('연계 업무 유형을 입력하세요.');
    if (bizId.trim() === '') throw new Error('연계 업무 식별자를 입력하세요.');
    const res = await call('POST', '/approval-documents', role, {
      approvalFormId: formId,
      title,
      body,
      linkedBusinessType: bizType,
      linkedBusinessId: bizId,
    });
    setRows([{ ...res, title, approvalFormId: formId }, ...rows]);
    setMode(null);
    notify('기안문을 임시저장했습니다.');
  }

  async function submit(row: Row) {
    const approvers = lines.filter((v) => v !== '');
    if (approvers.length === 0) throw new Error('결재선을 지정하세요.');
    const res = await call('POST', '/approval-documents/' + String(row['approvalDocumentId']) + '/submit', role, {
      approvalLines: approvers.map((id, i) => ({ approverId: id, order: i + 1 })),
    });
    setRows(rows.map((r) => (r['approvalDocumentId'] === row['approvalDocumentId'] ? { ...r, ...res } : r)));
    setMode(null);
    notify('기안문을 상신했습니다.');
  }

  function setLine(index: number, v: number | string) {
    setLines(lines.map((x, i) => (i === index ? v : x)));
  }

  return (
    <div className={'bento'}>
      <section className={'box span-12'}>
        <h2>처리 현황</h2>
        <Tiles items={[['임시저장', draftCount], ['상신', submittedCount]]} />
      </section>
      <section className={'box span-12'}>
        <h2>기안문</h2>
        <Band total={rows.length}>
          <button type={'button'} onClick={openCreate}>기안 작성</button>
        </Band>
        <DataTable
          rows={rows}
          empty={'작성한 기안문이 없습니다.'}
          columns={[
            { key: 'approvalDocumentId', label: '결재문서 ID' },
            { key: 'title', label: '문서 제목' },
            { key: 'approvalFormId', label: '결재양식', render: (r) => <RefName table={'approval_form'} role={role} value={r['approvalFormId']} /> },
            { key: 'documentNumber', label: '문서번호' },
            { key: 'approvalStatus', label: '결재 진행 상태', render: (r) => <Badge value={r['approvalStatus']} /> },
            { key: 'submittedAt', label: '상신 일시', render: (r) => <DateText value={r['submittedAt']} time /> },
            {
              key: 'action',
              label: '처리',
              render: (r) =>
                r['approvalStatus'] === '기안' ? (
                  <button type={'button'} onClick={() => openSubmit(r)}>상신</button>
                ) : null,
            },
          ]}
        />
      </section>
      {mode && mode.kind === 'create' && (
        <Drawer title={'기안 작성(임시저장)'} onClose={() => setMode(null)}>
          <Form onSubmit={create} submit={'임시저장'}>
            <Field label={'결재양식'} required>
              <LookupSelect table={'approval_form'} role={role} value={formId} onChange={setFormId} />
            </Field>
            <Field label={'문서 제목'} required wide>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label={'문서 본문'} wide>
              <TextInput value={body} onChange={setBody} multiline />
            </Field>
            <Field label={'연계 업무 유형'} required>
              <TextInput value={bizType} onChange={setBizType} />
            </Field>
            <Field label={'연계 업무 식별자'} required>
              <TextInput value={bizId} onChange={setBizId} />
            </Field>
          </Form>
        </Drawer>
      )}
      {mode && mode.kind === 'submit' && (
        <Drawer title={'기안문 상신'} onClose={() => setMode(null)}>
          <Form onSubmit={() => submit(mode.row)} submit={'상신'}>
            <Field label={'문서 제목'} wide>
              <span>{String(mode.row['title'] ?? '')}</span>
            </Field>
            {lines.map((v, i) => (
              <Field key={i} label={'결재자 ' + (i + 1)} required={i === 0} wide>
                <LookupSelect table={'employee'} role={role} value={v} onChange={(x) => setLine(i, x)} />
                {lines.length > 1 && (
                  <button type={'button'} onClick={() => setLines(lines.filter((_, j) => j !== i))}>삭제</button>
                )}
              </Field>
            ))}
            <button type={'button'} onClick={() => setLines([...lines, ''])}>결재자 추가</button>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
